fn largest_divisor(n: i8) -> i8 {
    // We assume n > 1 as per the problem statement.
    // The largest proper divisor of n is at most n/2.
    let n_i32 = n as i32;
    let max_candidate = n_i32 / 2;

    // Try candidates from n/2 down to 2. The first one that divides n
    // is the largest proper divisor > 1. If none divide, return 1.
    for k in (2..=max_candidate).rev() {
        if n_i32 % k == 0 {
            return k as i8;
        }
    }

    1
}